package com.wavjaby.jdbc.golden;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Stream;

/**
 * Characterization tests: they record what the processor emits today, bugs included, so a refactor that changes any
 * generated byte has to say so. A snapshot is evidence of current behaviour, never a claim that the behaviour is right.
 * <p>
 * Rewrite every snapshot after a deliberate change: {@code gradlew test -Dgolden.update=true}, then read the diff.
 */
class GoldenProcessorTest {

    private static final Path RESOURCES = Path.of(System.getProperty("golden.resourceDir"));
    private static final Path SCENARIOS = RESOURCES.resolve("scenarios");
    private static final Path SNAPSHOTS = RESOURCES.resolve("golden");
    private static final boolean UPDATE = Boolean.parseBoolean(System.getProperty("golden.update", "false"));

    static Stream<String> scenarios() throws IOException {
        try (Stream<Path> dirs = Files.list(SCENARIOS)) {
            return dirs.filter(Files::isDirectory)
                    .map(p -> p.getFileName().toString())
                    .sorted()
                    .toList()
                    .stream();
        }
    }

    @ParameterizedTest(name = "{0}")
    @MethodSource("scenarios")
    void scenario(String name) throws IOException {
        List<Path> sources;
        try (Stream<Path> walk = Files.walk(SCENARIOS.resolve(name))) {
            sources = walk.filter(p -> p.getFileName().toString().endsWith(".java"))
                    .sorted(Comparator.comparing(Path::toString))
                    .toList();
        }
        Assertions.assertFalse(sources.isEmpty(), "scenario has no fixture sources: " + name);

        String actual = render(ProcessorRunner.run(name, sources));
        Path snapshot = SNAPSHOTS.resolve(name + ".txt");

        if (UPDATE || !Files.exists(snapshot)) {
            Files.createDirectories(SNAPSHOTS);
            Files.writeString(snapshot, actual, StandardCharsets.UTF_8);
            System.out.println((UPDATE ? "updated " : "created ") + snapshot.getFileName());
            return;
        }
        String expected = Files.readString(snapshot, StandardCharsets.UTF_8).replace("\r\n", "\n");
        Assertions.assertEquals(expected, actual,
                "processor output changed for '" + name + "'. Read the diff, decide which side is right, then rerun with -Dgolden.update=true");
    }

    private static String render(ProcessorRunner.Result result) {
        StringBuilder out = new StringBuilder();
        out.append("=== diagnostics (").append(result.diagnostics().size()).append(") ===\n");
        result.diagnostics().forEach(d -> out.append(d).append('\n'));
        for (ProcessorRunner.GeneratedFile file : result.generated()) {
            out.append("\n=== generated: ").append(file.path()).append(" ===\n");
            out.append(file.content()).append('\n');
        }
        return out.toString();
    }
}
